CREATE TABLE IF NOT EXISTS `god2_game`.`public_beta_skill_effect_v0` (
    `global_record_id` int NOT NULL,
    `record_id_in_bank` int NOT NULL,
    `bank` int NOT NULL,
    `slot_one_based` int NOT NULL,
    `name_zh_tw` varchar(256) NULL,
    `description_zh_tw` varchar(500) NULL,
    `level_candidate` int NULL,
    `implementation_family` varchar(64) NOT NULL,
    `effect_kind` varchar(32) NOT NULL,
    `status_or_axis` varchar(64) NULL,
    `mp_cost` int NULL,
    `target_context` int NULL,
    `target_scope` int NULL,
    `numeric_effect_fields` varchar(1000) NULL,
    `v0_to_v23_nonzero` varchar(1500) NULL,
    `minimum_working_server_rule` varchar(1500) NOT NULL,
    `provisional_success_rule` varchar(500) NULL,
    `provisional_duration_rule` varchar(500) NULL,
    `packet_evidence_boundary` varchar(1500) NOT NULL,
    `source_file` varchar(128) NOT NULL DEFAULT 'server-skill-effects-v0-implementation-plan.csv',
    `source_sha256` char(64) NOT NULL,
    `enabled` tinyint(1) NOT NULL DEFAULT 1,
    `created_at_utc` datetime(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),
    `updated_at_utc` datetime(6) NOT NULL DEFAULT UTC_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    PRIMARY KEY (`global_record_id`),
    KEY `ix_public_beta_skill_effect_family` (`implementation_family`),
    KEY `ix_public_beta_skill_effect_kind` (`effect_kind`),
    CONSTRAINT `ck_public_beta_skill_effect_enabled` CHECK (`enabled` IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='公測版 cbspec2 技能 buff/effect v0 服務端對照';

